fn solve(x: i32) -> i32 {
    // x is a "boring" apartment number with digit d repeated k times
    // Extract d and k from x
    // For example, if x=777, then d=7, k=3

    let x_str = x.to_string();
    let k = x_str.len() as i32;
    let d = x_str.chars().next().unwrap().to_digit(10).unwrap() as i32;

    // The score is the total number of button presses for:
    // - all boring numbers with digits < d (each with lengths 1 to 4)
    // - plus all boring numbers with digit d up to length k

    // Each boring number with length l = l presses.

    // Number of boring numbers for each digit = 4 (from length 1 to 4)
    // Each digit less than d contributes 1+2+3+4 = 10 presses
    // For digit d, only lengths 1 to k contribute presses: sum(1..=k) = k*(k+1)/2

    let presses_before = (d - 1) * 10; // sum for all digits < d
    let presses_current = k * (k + 1) / 2;

    presses_before + presses_current
}